-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.award_certificate(p_design uuid, p_profile uuid, p_challenge uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_id uuid;
begin
  if not public.is_admin() then
    raise exception 'Only an admin can award a certificate';
  end if;
  insert into public.certificate_awards
    (design_id, profile_id, challenge_id, community_id, facts, serial, awarded_by)
  select p_design, p_profile, p_challenge, c.community_id,
         jsonb_strip_nulls(jsonb_build_object(
           'name',      p.name,
           'challenge', c.title,
           'market',    com.name,
           'note',      nullif(btrim(coalesce(p_note, '')), ''),
           'date',      now()
         )),
         public.certificate_serial(),
         auth.uid()
  from public.profiles p
  left join public.challenges c on c.id = p_challenge
  left join public.communities com on com.id = c.community_id
  where p.id = p_profile
  on conflict do nothing
  returning id into new_id;
  return new_id;
end $function$;
